export function step(state, dt) {
  const { ball, paddle } = state;

  // Substep the integration so a fast ball cannot jump clean over a brick in
  // one frame ("tunnelling"): each substep advances the ball by at most ~4 px,
  // far less than the 14 px ball and the 34 px brick pitch, so every swept
  // overlap is caught. dt is already clamped to 0.05 s upstream.
  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const subSteps = Math.max(1, Math.min(64, Math.ceil(distance / 4)));
  const subDt = dt / subSteps;

  for (let s = 0; s < subSteps; s++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Bricks. Overlaps are gathered in a first pass so that, when the ball
    // straddles the seam between two neighbours in the same frame, every brick
    // it touches is broken but the bounce is applied EXACTLY once (a double
    // `vy = -vy` would cancel and let the ball through). The chosen face is the
    // one with the least penetration, so a clean face hit is answered by a
    // single perpendicular flip.
    const overlapped = [];
    for (const brick of state.bricks) {
      if (brick.alive && collides(ball, brick)) overlapped.push(brick);
    }
    if (overlapped.length > 0) {
      for (const brick of overlapped) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
      let chosen = overlapped[0];
      let smallest = Infinity;
      for (const brick of overlapped) {
        const p = Math.min(penetrateX(ball, brick), penetrateY(ball, brick));
        if (p < smallest) {
          smallest = p;
          chosen = brick;
        }
      }
      reflectBall(ball, chosen);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

